<?php declare(strict_types=1); require dirname(__DIR__).'/autoload.php'; ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Authentication Test</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f6f7fb}.card{border:0;box-shadow:0 .3rem 1rem rgba(0,0,0,.06)}pre{background:#111827;color:#e5e7eb;padding:14px;border-radius:10px;white-space:pre-wrap}</style></head><body><div class="container py-4"><a href="index.php" class="btn btn-sm btn-outline-secondary mb-3">← Test Merkezi</a><h1 class="h3">Authentication Test</h1><?php $out=null;$err=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{$s=new ScratchByPHP\Scratch();$mode=$_POST['mode']??'password';if($mode==='session'){$session=$s->loginWithSessionId(trim((string)$_POST['sid']),trim((string)($_POST['username']??''))?:null);}else{$session=$s->login(trim((string)$_POST['username']), (string)$_POST['password']);}$out=$session->debug();}catch(Throwable $e){$err=$e->getMessage();}}?><div class="alert alert-info">Bu panel yalnızca tek hesapla login/session teşhisi yapar; hiçbir follow/love/favorite işlemi yapmaz ve credential kaydetmez.</div><div class="card"><div class="card-body"><form method="post" autocomplete="off"><div class="mb-2"><select name="mode" class="form-select"><option value="password">Username + Password</option><option value="session">Session ID</option></select></div><input class="form-control mb-2" name="username" placeholder="Username"><input class="form-control mb-2" name="password" type="password" placeholder="Password"><textarea class="form-control mb-2" name="sid" placeholder="Session ID"></textarea><button class="btn btn-primary">Login Test</button></form><?php if($err):?><div class="alert alert-danger mt-3"><?=htmlspecialchars($err)?></div><?php elseif($out):?><pre class="mt-3"><?=htmlspecialchars(json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre><?php endif;?></div></div></div></body></html>